import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/material.dart';
import 'package:flutter/semantics.dart';
import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:flutter_web_plugins/url_strategy.dart';

import 'app.dart';
import 'core/utils/shein_bloc_observer.dart';
import 'firebase_options.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();

  // Real path URLs (/catalog/women) instead of hash URLs (#/catalog/women).
  usePathUrlStrategy();

  // 1) Firebase (options generated by `flutterfire configure`).
  await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);

  // 2) Always expose the semantics tree — accessibility support and makes
  //    the UI drivable by automated e2e tests (Playwright accessibility API).
  SemanticsBinding.instance.ensureSemantics();

  // 3) Bloc logging.
  Bloc.observer = SheinBlocObserver();

  runApp(SheinApp());
}
